// DeployDiesisConfigBinding deploys caller-supplied bytecode with typed constructor arguments.
func DeployDiesisConfigBinding(opts *bind.TransactOpts, backend bind.ContractBackend, bytecode []byte, params DiesisConfigConstructorParams) (common.Address, *types.Transaction, *DiesisConfigBinding, error) {
	if opts == nil || backend == nil {
		return common.Address{}, nil, nil, fmt.Errorf("transaction options and backend are required")
	}
	if len(bytecode) == 0 {
		return common.Address{}, nil, nil, fmt.Errorf("deployment bytecode is empty")
	}
	if opts.Value != nil && opts.Value.Sign() != 0 {
		return common.Address{}, nil, nil, fmt.Errorf("constructor is not payable")
	}
	parsed, err := abi.JSON(strings.NewReader(DiesisConfigABI))
	if err != nil {
		return common.Address{}, nil, nil, err
	}
	address, tx, _, err := bind.DeployContract(opts, parsed, bytecode, backend, params.Owner)
	if err != nil {
		return common.Address{}, nil, nil, err
	}
	binding, err := NewDiesisConfigBinding(address, backend)
	if err != nil {
		return common.Address{}, nil, nil, err
	}
	return address, tx, binding, nil
}

