// DecodeOutOfRangeError decodes a "OutOfRange()" revert payload, including its selector.
func (c *DiesisConfigBinding) DecodeOutOfRangeError(raw []byte) (out DiesisConfigOutOfRangeError, err error) {
	defer func() {
		if failure := recover(); failure != nil {
			err = fmt.Errorf("invalid ABI error: %v", failure)
		}
	}()
	definition, err := c.customError("OutOfRange()")
	if err != nil {
		return out, err
	}
	if len(raw) < 4 || !bytes.Equal(raw[:4], definition.ID[:4]) {
		return out, fmt.Errorf("error selector mismatch for %s", "OutOfRange()")
	}
	values, err := definition.Inputs.Unpack(raw[4:])
	if err != nil {
		return out, err
	}
	if len(values) != 0 {
		return out, fmt.Errorf("error value count mismatch")
	}
	return out, nil
}

