// DecodeError identifies and decodes a declared custom error.
func (c *DiesisConfigBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("OutOfRange()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOutOfRangeError(raw)
	}
	if definition, err := c.customError("OwnableInvalidOwner(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOwnableInvalidOwnerError(raw)
	}
	if definition, err := c.customError("OwnableUnauthorizedAccount(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOwnableUnauthorizedAccountError(raw)
	}
	if definition, err := c.customError("SumExceedsOne()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeSumExceedsOneError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
